        $document = $this->resource;

        return [
            'type' => $document->type,
            'schema_version' => $document->schemaVersion,
            'state_version' => $document->stateVersion,
            'collab_epoch' => $document->epoch,
50→            'revision_id' => $document->headRevisionId,
            'content' => self::readable($document->content),
